create table if not exists users (id uuid primary key default gen_random_uuid(), email text not null unique, password_hash text, created_at timestamptz not null default now());
create table if not exists sessions (token_hash text primary key, user_id uuid not null references users(id) on delete cascade, expires_at timestamptz not null, created_at timestamptz not null default now());
create table if not exists conversations (id uuid primary key default gen_random_uuid(), title text not null check (char_length(title) between 1 and 60), created_by uuid not null references users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists conversation_members (conversation_id uuid not null references conversations(id) on delete cascade, user_id uuid not null references users(id) on delete cascade, role text not null default 'member' check (role in ('owner','member')), joined_at timestamptz not null default now(), primary key (conversation_id,user_id));
create table if not exists user_keys (user_id uuid primary key references users(id) on delete cascade, public_key jsonb not null, updated_at timestamptz not null default now());
create table if not exists messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references conversations(id) on delete cascade, user_id uuid not null references users(id) on delete cascade, encrypted_payload jsonb not null, created_at timestamptz not null default now());
create table if not exists attachments (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references conversations(id) on delete cascade, user_id uuid not null references users(id) on delete cascade, blob_path text not null, filename text not null, content_type text not null, byte_size integer not null check(byte_size > 0 and byte_size <= 10485760), encrypted_file_key jsonb, created_at timestamptz not null default now());
create index if not exists messages_cursor_idx on messages(conversation_id,created_at,id);
create index if not exists members_user_idx on conversation_members(user_id,conversation_id);
create index if not exists attachments_room_idx on attachments(conversation_id,created_at);
